import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# -------------------------------------------------------------------------
# 1) Custom CUDA operator: element-wise addition (reuse from the example)
# -------------------------------------------------------------------------
elementwise_add_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void elementwise_add_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = a[idx] + b[idx];
    }
}

torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b) {
    auto size = a.numel();
    auto out = torch::zeros_like(a);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    elementwise_add_kernel<<<num_blocks, block_size>>>(a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), size);

    return out;
}
"""

elementwise_add_cpp_source = "torch::Tensor elementwise_add_cuda(torch::Tensor a, torch::Tensor b);"

elementwise_add = load_inline(
    name="elementwise_add",
    cpp_sources=elementwise_add_cpp_source,
    cuda_sources=elementwise_add_source,
    functions=["elementwise_add_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# -------------------------------------------------------------------------
# 2) Custom CUDA operator: naive 2D convolution (square kernel, square input)
# -------------------------------------------------------------------------
conv2d_kernel = """
__global__ void conv2d_kernel(const float* input, const float* weight, float* output,
                               int B, int C_in, int C_out, int KH, int KW, int stride, int padding, int dilation,
                               int H_out, int W_out) {
    // Compute global index for each thread
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= B * C_out * H_out * W_out) return;

    // Decompose idx into b, oc, oy, ox
    const int out_elements_per_channel = H_out * W_out;
    int tmp = idx;
    int b = tmp / out_elements_per_channel;
    tmp %= out_elements_per_channel;
    int oc = tmp / (H_out * W_out);
    tmp %= (H_out * W_out);
    int oy = tmp / W_out;
    int ox = tmp % W_out;

    float sum = 0.0f;
    for (int ic = 0; ic < C_in; ++ic) {
        for (int kh = -dilation; kh < KH + dilation; ++kh) {
            int ih = oy * stride * padding + kh;
            if (ih >= 0 && ih < H) { // need H from input size
                int iw = ox * stride * padding + (kh >= 0 ? kh : -kh);
                if (iw >= 0 && iw < W) {
                    const float a_val = input[(b * C_in + ic) * H * W + ih * W + iw];
                    const int w_idx = ((oc * C_in + ic) * KH * KW + kh) * KW + iw;
                    if (w_idx < size(weight)) {
                        const float w_val = weight[w_idx];
                        sum += a_val * w_val;
                    }
                }
            }
        }
    }
    output[idx] = sum;
}
"""

conv2d_cuda_source = """
torch::Tensor conv2d_cuda(torch::Tensor input, torch::Tensor weight) {
    // input: (B, C_in, H, W)
    // weight: (C_out, C_in, KH, KW)
    const int B = input.size(0);
    const int C_in = input.size(1);
    const int H = input.size(2);
    const int W = input.size(3);

    const int H_out = (H - KH + 2*padding) / stride + 1;
    const int W_out = (W - KW + 2*padding) / stride + 1;

    torch::Tensor out = torch::zeros(B, C_out, H_out, W_out);

    // Launch kernel
    const int block_size = 256;
    const int num_blocks_x = ((H_out * W_out + block_size - 1) / block_size);
    const int num_blocks_y = (B * C_out * H_out * W_out + block_size - 1) / block_size;

    conv2d_kernel<<<num_blocks_x, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C_in, C_out, KH, KW, stride, padding, dilation,
        H_out, W_out
    );

    return out;
}
"""

conv2d_cpp_source = ""

conv2d = load_inline(
    name="conv2d",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_cuda_source,
    functions=["conv2d_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

# -------------------------------------------------------------------------
# 3) Optimized model that replaces the convolution with our custom CUDA op
# -------------------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.elementwise_add = elementwise_add   # already a custom operator
        self.conv2d = conv2d                    # custom convolution kernel

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height, width).

        Returns:
            Output tensor after 2D convolution.
        """
        return self.conv2d(x)
